import {options,categoryDetails} from './business.js';
import {photography} from './photography.js';
import {money} from './content.js';
const categories=['Sedan','SUV','Sprinter'];
export function startShowroom(path){
 const root=document.querySelector('.private-showroom');if(!root)return;
 const host=document.querySelector('#photo-host'),query=new URLSearchParams(location.search),reduced=matchMedia('(prefers-reduced-motion: reduce)');let chosen=Number(query.get('option'));
 if(!query.has('option')||!Number.isInteger(chosen)||chosen<0||chosen>=options.length)chosen=Math.max(0,categories.findIndex(c=>path.endsWith('/'+c.toLowerCase())));
 let current=options[chosen].category,booking=false,frame=null,loadTimer,animationTimer,photoRequest=0;
 const serviceSelect=document.querySelector('#showroom-service'),bookingSelect=document.querySelector('#booking-service');
 async function showPhoto(category){if(host.dataset.category===category)return;const request=++photoRequest,photo=photography[category],image=new Image();image.src=photo.src;image.alt=photo.alt;image.className='vehicle-photo';image.style.objectPosition=photo.position;try{await image.decode()}catch{return}if(request!==photoRequest)return;host.dataset.category=category;const old=host.querySelector('.vehicle-photo');host.querySelector('.photo-atmosphere').src=photo.src;host.append(image);if(!reduced.matches){image.animate([{opacity:0},{opacity:1}],{duration:800,easing:'ease-out'});setTimeout(()=>old?.remove(),850)}else old?.remove()}
 function refresh(){current=options[chosen].category;serviceSelect.value=String(chosen);bookingSelect.value=String(chosen);document.querySelectorAll('[data-showroom-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.showroomCategory===current)));const index=categories.indexOf(current);document.querySelector('#showroom-index').textContent=`0${index+1} / 03`;document.querySelector('#photo-index').textContent=`0${index+1} / ${current.toUpperCase()} COLLECTION`;document.querySelector('#showroom-description').innerHTML=`<h2>Luxury ${current}</h2><h3>${categoryDetails[current].headline}</h3><p>${categoryDetails[current].description}</p><p class="showroom-price">${money(options[chosen].price)} <small>/ one-hour listing</small></p>`;document.querySelector('#compact-category').textContent='Luxury '+current;document.querySelector('#reservation-service-label').textContent=`${options[chosen].name} · ${money(options[chosen].price)} · 1 hour`;document.querySelector('#external-booking').href=options[chosen].bookingUrl;showPhoto(current)}
 function updateFrame(){if(!frame){frame=document.createElement('iframe');frame.id='live-scheduler';frame.title='Martinez Logistics live Acuity reservation calendar';frame.allow='payment';frame.referrerPolicy='strict-origin-when-cross-origin';frame.addEventListener('load',()=>{clearTimeout(loadTimer);document.querySelector('#scheduler-status').textContent='Live availability provided by Acuity Scheduling.'});document.querySelector('#scheduler-mount').append(frame)}const url=new URL(options[chosen].bookingUrl);for(const [key,value]of Object.entries({bodyBackground:'121416',headerText:'f2f0eb',schedulerBackground:'121416',schedulerText:'f2f0eb',buttonAccent:'c4a66b',buttonText:'08090a'}))url.searchParams.set(key,value);document.querySelector('#scheduler-status').textContent='Preparing your reservation calendar…';frame.src=url.href;clearTimeout(loadTimer);loadTimer=setTimeout(()=>document.querySelector('#scheduler-status').textContent='If the calendar cannot load, open booking in a new tab below.',12000)}
 function setBooking(value,push=true){booking=value;root.classList.toggle('is-booking',value);document.querySelector('.reservation-panel').hidden=!value;document.querySelector('.showroom-copy').hidden=value;document.querySelector('.model-booking-summary').hidden=!value;refresh();if(value){updateFrame();clearTimeout(animationTimer);animationTimer=setTimeout(()=>document.querySelector('#reservation-heading').focus({preventScroll:true}),reduced.matches?0:700)}if(push)history.pushState({showroomBooking:value,chosen},'',`/reserve/?option=${chosen}${value?'&booking=1':''}`)}
 function chooseCategory(category){chosen=options.findIndex(o=>o.category===category&&o.type==='Hourly');refresh();history.replaceState({showroomBooking:false,chosen},'',`/fleet/${category.toLowerCase()}/`)}
 document.querySelectorAll('[data-showroom-category]').forEach(b=>b.addEventListener('click',()=>chooseCategory(b.dataset.showroomCategory)));
 for(const [id,direction]of [['previous-vehicle',-1],['next-vehicle',1]])document.querySelector('#'+id).addEventListener('click',()=>chooseCategory(categories[(categories.indexOf(current)+direction+3)%3]));
 serviceSelect.addEventListener('change',()=>{chosen=Number(serviceSelect.value);refresh();history.replaceState({showroomBooking:false,chosen},'',`/reserve/?option=${chosen}`)});
 bookingSelect.addEventListener('change',()=>{chosen=Number(bookingSelect.value);refresh();updateFrame();history.replaceState({showroomBooking:true,chosen},'',`/reserve/?option=${chosen}&booking=1`)});
 document.querySelector('#select-vehicle').addEventListener('click',()=>setBooking(true));document.querySelector('#back-to-showroom').addEventListener('click',()=>setBooking(false));document.querySelector('#change-vehicle').addEventListener('click',()=>setBooking(false));
 addEventListener('popstate',()=>{const p=new URLSearchParams(location.search),index=Number(p.get('option'));if(p.has('option')&&Number.isInteger(index)&&index>=0&&index<options.length)chosen=index;setBooking(p.get('booking')==='1',false)});
 // Adjacent category photographs preload without blocking the first image.
 for(const category of categories){const image=new Image();image.src=photography[category].src}
 refresh();if(query.get('booking')==='1')setBooking(true,false);addEventListener('pagehide',()=>{clearTimeout(loadTimer);clearTimeout(animationTimer)},{once:true});
}
